document.addEventListener('DOMContentLoaded',()=>{const grid=document.getElementById('clubsGrid');const cards=Array.from(document.querySelectorAll('.club-card'));const searchInput=document.getElementById('clubSearch');const sortTabs=document.querySelectorAll('.filter-tab');const resultsCount=document.getElementById('resultsCount');const noResults=document.getElementById('noResults');function applySearch(){const query=(searchInput?.value||'').trim();let visibleCount=0;cards.forEach(card=>{const visible=!query||card.dataset.name.includes(query);card.hidden=!visible;if(visible)visibleCount++});resultsCount.textContent=visibleCount;noResults.hidden=visibleCount!==0;grid.hidden=visibleCount===0}
searchInput?.addEventListener('input',applySearch);sortTabs.forEach(tab=>{tab.addEventListener('click',()=>{sortTabs.forEach(t=>t.classList.remove('active'));tab.classList.add('active');const sort=tab.dataset.sort;let sorted=cards;if(sort==='popular'){sorted=[...cards].sort((a,b)=>b.dataset.members-a.dataset.members)}
sorted.forEach(card=>grid.appendChild(card))})});document.querySelectorAll('.club-card-footer .btn').forEach(btn=>{btn.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();const joined=btn.classList.toggle('joined');btn.textContent=joined?'منضم':'انضمام'})});document.querySelector('.create-club-banner .btn-gold')?.addEventListener('click',function(){this.innerHTML='<i class="fa-solid fa-check"></i> قريبًا!';setTimeout(()=>{this.innerHTML='<i class="fa-solid fa-plus"></i> إنشاء نادي جديد'},1800)})})